+        console.error(`  ✗ Error processing message: ${error}`);
+        
+        // Abandon the message (return to queue for retry)
+        await receiver.abandonMessage(message);
+        console.log(`  ⚠ Abandoned message: ${message.messageId}`);
+      }
+    }
+  } finally {
+    await receiver.close();
+  }
+}
